"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { alertRecipe } from "@/lib/ink/recipes/alert-ink"
import { cn } from "@/lib/utils"

const alertVariants = cva(
  "relative isolate w-full overflow-hidden rounded-[var(--radius-md)] px-4 py-3 text-sm",
  {
    variants: {
      variant: {
        default: "text-foreground",
        success: "text-foreground",
        warning: "text-foreground",
        destructive: "text-foreground",
        info: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
)

function Alert({
  className,
  variant,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof alertVariants> & {
    seed?: string | number
  }) {
  const v = variant ?? "default"
  const { hostRef, hostProps, node } = useInk({
    recipe: alertRecipe,
    params: { variant: v },
    kind: "alert",
    seed,
    still: true,
  })

  return (
    <div
      data-slot="alert"
      role="alert"
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      data-variant={v}
      className={cn(alertVariants({ variant: v, className }))}
      {...props}
    >
      {node}
      <div className="relative z-[1] grid gap-1">{children}</div>
    </div>
  )
}

function AlertTitle({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-title"
      ref={ref}
      className={cn("font-semibold tracking-tight", className)}
      {...props}
    />
  )
}

function AlertDescription({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      ref={ref}
      className={cn("text-muted-foreground [&_p]:leading-relaxed", className)}
      {...props}
    />
  )
}

export { Alert, AlertDescription, AlertTitle, alertVariants }

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import type { PaintKey } from '@/lib/ink/paint'
import type { PenName } from '@/lib/ink/types'
import { softFill } from '@/lib/ink/recipes/wash-utils'
import { drawSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const alertVariantList = ['default', 'success', 'warning', 'destructive', 'info'] as const
export type AlertVariant = (typeof alertVariantList)[number]

const accent: Record<AlertVariant, { fill: PaintKey; wash: PaintKey; pen: PenName }> = {
  default: { fill: 'rose-wash', wash: 'rose', pen: 'rose.fine' },
  success: { fill: 'baobab', wash: 'baobab', pen: 'baobabfelt.fine' },
  warning: { fill: 'ember', wash: 'wash-gold', pen: 'ember.fine' },
  destructive: { fill: 'ember-deep', wash: 'danger', pen: 'ember.fine' },
  info: { fill: 'horizon', wash: 'horizon', pen: 'horizonPencil.fine' },
}

export interface AlertParams {
  variant: AlertVariant
}

export const alertRecipe = defineRecipe<AlertParams>({
  id: 'alert',
  kind: 'alert',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }, { variant }) {
    const { fill, wash: washKey, pen } = accent[variant]
    const r = clamp(Math.min(w, h) * 0.05, 5, 10)
    const stripW = clamp(w * 0.04, 4, 7)
    const strip = roundRectPoly(0.8, 0.8, stripW, h - 1.6, Math.min(3, r))

    ink.layer('rest', () => {
      drawSandSlipPanel(ink, w, h, 'default')
      softFill(ink, strip, [
        { color: fill, alpha: 0.55, wobble: 0.55 },
        { color: washKey, alpha: 0.28, inset: 0.45 },
      ])
      wash(ink, roundRectPoly(stripW + 2, 1.2, w - stripW - 3, h - 2.4, r - 1), fill, {
        alpha: 0.1,
        material: 'wash',
        wobble: 0.65,
      })
      box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
        pen,
        corner: r,
        loose: 0.85,
        opts: { alpha: 0.42, simple: w > 360, color: 'line-soft' },
      })
    })
  },
})

import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type PanelTone = 'default' | 'lifted'

/** Compact sand-slip panel (Tooltip / Toast). */
export function drawCompactSandSlipPanel(ink: Ink, w: number, h: number) {
  const r = clamp(Math.min(w, h) * 0.1, 4, 7)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.82, wobble: 0.48 },
      { color: 'sand', alpha: 0.28, inset: 0.9, wobble: 0.55 },
      { color: 'wash-gold', alpha: 0.06, inset: 1.6, wobble: 0.9 },
    ])
  })
  box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
    pen: 'pencil.fine',
    corner: r,
    loose: 0.95,
    opts: { alpha: 0.48, wobble: 0.38, simple: w > 280 },
  })
  box(ink, 1.1, 1.1, w - 2.2, h - 2.2, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1,
    opts: { alpha: 0.18, wobble: 0.42, simple: true, color: 'line-soft' },
  })
}

/** Sand-slip panel fill + double loose border (Card / Dialog / Popover). */
export function drawSandSlipPanel(ink: Ink, w: number, h: number, tone: PanelTone = 'default') {
  const r = clamp(Math.min(w, h) * 0.04, 5, 12)
  const inset = 0.7
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: tone === 'lifted' ? 0.9 : 0.78, wobble: 0.5 },
      { color: 'sand', alpha: 0.32, inset: 1.2, wobble: 0.65 },
      { color: 'wash-gold', alpha: 0.08, inset: 2.4, wobble: 1.1 },
    ])
  })
  box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
    pen: 'pencil.fine',
    corner: r,
    loose: 1.15,
    opts: { alpha: 0.52, wobble: 0.42, simple: w > 420 },
  })
  box(ink, 1.4, 1.4, w - 2.8, h - 2.8, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1.25,
    opts: { alpha: 0.22, wobble: 0.5, simple: true, color: 'line-soft' },
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
